package apply

import (
	"context"
	"time"

	userv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/identity/user/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-identity/internal/legacy"
)

// UserReader is the slice of internal/legacy.Reader the apply loop
// needs. Defined here so tests inject fakes and don't require a real
// pgx pool.
type UserReader interface {
	ListUsers(ctx context.Context, tenantID, cursor int64, limit int) ([]legacy.User, error)
}

// TenantLookup is the slice of internal/target.TenantClient the apply
// loop uses to translate the cutover tenant's legacy organization_id
// → new tenant UUID at startup.
type TenantLookup interface {
	GetByLegacyId(ctx context.Context, req *tenantv1.GetByLegacyIdRequest) (*tenantv1.GetByLegacyIdResponse, error)
}

// UserInviter is the slice of internal/target.UserClient the apply
// loop uses to write each user.
type UserInviter interface {
	Invite(ctx context.Context, req *userv1.InviteRequest) (*userv1.InviteResponse, error)
}

// CursorBackend matches platform/libs/go/migrator.Cursor's Get/Put
// surface so production passes the real Cursor and tests pass an
// in-memory backend.
type CursorBackend interface {
	Get(ctx context.Context, binary, tenant, entity string) (int64, bool, error)
	Put(ctx context.Context, binary, tenant, entity string, offset int64) error
}

// Reporter matches platform/libs/go/migrator.Rejection's Write
// surface.
type Reporter interface {
	Write(entry migrator.RejectionEntry) error
}

// MetricsSink matches platform/libs/go/migrator.Metrics's emission
// methods.
type MetricsSink interface {
	RowsPlanned(ctx context.Context, tenant, entity string)
	RowsApplied(ctx context.Context, tenant, entity, result string)
	RecordApplyDuration(ctx context.Context, tenant, entity string, dur time.Duration)
	SetLagRows(ctx context.Context, tenant, entity string, n int64)
	RejectionsInc(ctx context.Context, tenant, entity, errorCode string)
	TokenRefreshInc(ctx context.Context)
}


