package apply

// Summary is the per-run tally returned by orchestrator.Run. Mirrors
// migrator-org's apply.Summary so operator-facing tooling sees the
// same JSON shape across binaries.
//
// Counted by row, not by RPC: a row that hits ALREADY_EXISTS is
// counted once as Applied (with sub-result "upserted"), not twice.
type Summary struct {
	Planned  int
	Applied  int
	Rejected int
	Errored  int
}


