		BatchSize: 10,
		DryRun:    true,
		Retry: &apply.RetryPolicy{
			MaxAttempts: 5,
			Sleep:       func(context.Context, time.Duration) error { return nil },
		},
	})
	require.NoError(t, err)

	_, err = o.Run(context.Background())
	require.NoError(t, err)
	require.Empty(t, cursor.store, "DryRun must NOT write to cursor — checkpointing in plan mode would corrupt subsequent applies")
}

// TestRun_DryRun_TerminatesWithCursorAwareReader pins the fix for
// issue #53. When the reader's ListUsers honours the cursor (as the
// real legacy.Reader does), plan mode used to loop forever because
// the apply loop only advanced the persisted cursor for non-dry-run
// runs. With the local-cursor fix, plan mode walks each row exactly
// once and returns once the reader reports the page is empty.
//
// Without the fix this test deadlocks; the runtime watchdog below
// turns that into a fast failure rather than a stuck CI run.
func TestRun_DryRun_TerminatesWithCursorAwareReader(t *testing.T) {
	rows := []legacy.User{
		{ID: 1, HomeOrganizationID: 42, Email: "a@example.com", Username: "a", IsActive: true},
		{ID: 2, HomeOrganizationID: 42, Email: "b@example.com", Username: "b", IsActive: true},
		{ID: 3, HomeOrganizationID: 42, Email: "c@example.com", Username: "c", IsActive: true},
	}
	r := &cursorReader{rows: rows}
	o, _ := newUsersWithReader(t, r, tenantOK("u"), &fakeInviter{}, true)

	done := make(chan struct{})
	var sum apply.Summary
	var runErr error
	go func() {
		defer close(done)
		sum, runErr = o.Run(context.Background())
	}()

	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not terminate within 2s — cursor never advanced in dry-run (issue #53)")
	}

	require.NoError(t, runErr)
	require.Equal(t, 3, sum.Planned, "every row processed exactly once")
	require.Equal(t, 3, sum.Applied)
	// Reader should be called once for the page of 3 + once more to see the empty page.
	require.Equal(t, 2, r.calls, "reader walked once forward, then saw empty page")
}



