// Package apply orchestrates the legacy → target migration loop.
//
// The package is deliberately interface-driven (see interfaces.go):
// the orchestrator depends on Reader, Target, Cursor, Reporter, and
// Metrics interfaces, so unit tests inject in-memory fakes and the
// state-machine logic exercises the full §9 error matrix without any
// real network or database. Production wires real implementations
// from internal/legacy, internal/target, and platform/libs/go/migrator.
package apply

import (
	"context"
	"time"
)

// RetryDecision is the verdict the operation function returns to
// WithBackoff. Done means success — no further attempts. Retry means
// transient failure — wait and try again. HardFail means terminal —
// surface the error immediately, no further attempts.
type RetryDecision int

const (
	RetryDecisionDone RetryDecision = iota
	RetryDecisionRetry
	RetryDecisionHardFail
)

// RetryPolicy configures WithBackoff.
type RetryPolicy struct {
	MaxAttempts int
	Sleep       func(ctx context.Context, d time.Duration) error
}

// WithBackoff invokes op() repeatedly with exponential backoff
// (1s, 2s, 4s, 8s, 16s — capped at MaxAttempts attempts total).
// Schedule matches spec §9 ("UNAVAILABLE: backoff retry
// 1s/2s/4s/8s/16s; after 5 attempts hard fail").
func WithBackoff(ctx context.Context, p RetryPolicy, op func() (RetryDecision, error)) error {
	attempts := p.MaxAttempts
	if attempts < 1 {
		attempts = 1
	}

	delay := time.Second
	var lastErr error
	for i := 0; i < attempts; i++ {
		decision, err := op()
		switch decision {
		case RetryDecisionDone:
			return nil
		case RetryDecisionHardFail:
			return err
		case RetryDecisionRetry:
			lastErr = err
			if i == attempts-1 {
				return lastErr
			}
			if sleepErr := p.Sleep(ctx, delay); sleepErr != nil {
				return sleepErr
			}
			delay *= 2
		}
	}
	return lastErr
}

// RealSleep is a Sleep implementation backed by time.NewTimer + ctx.Done().
func RealSleep(ctx context.Context, d time.Duration) error {
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}


