	calls := 0
	err := apply.WithBackoff(context.Background(), apply.RetryPolicy{
		MaxAttempts: 0,
		Sleep:       func(context.Context, time.Duration) error { return nil },
	}, func() (apply.RetryDecision, error) {
		calls++
		return apply.RetryDecisionRetry, errors.New("x")
	})
	require.Error(t, err)
	require.Equal(t, 1, calls,
		"degenerate MaxAttempts=0 must still try once so caller never gets a no-op success")
}


