package apply

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-identity/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-identity/internal/mapper"
)

const binaryName = "migrator-identity"
const entityUsers = "users"

// UsersConfig wires the phase-2 orchestrator's deps + behaviour.
type UsersConfig struct {
	Reader   UserReader
	Tenants  TenantLookup
	Inviter  UserInviter
	Cursor   CursorBackend
	Reporter Reporter
	Metrics  MetricsSink

	RunID     string
	TenantID  int64 // legacy organizations.id
	BatchSize int   // rows per ListUsers call
	DryRun    bool
	Retry     *RetryPolicy
}

// Users is phase 2 of the cutover: paginate the legacy users table for
// the configured tenant, resolve the tenant UUID once at startup, then
// for each row build an InviteRequest and call
// identity-svc.UserService.Invite. Cursor advances per row so a
// mid-batch crash resumes cleanly.
type Users struct {
	cfg UsersConfig
}

// NewUsers validates config and returns the orchestrator.
func NewUsers(cfg UsersConfig) (*Users, error) {
	if cfg.Reader == nil {
		return nil, errors.New("apply: Reader required")
	}
	if cfg.Tenants == nil {
		return nil, errors.New("apply: Tenants lookup required")
	}
	if cfg.Inviter == nil {
		return nil, errors.New("apply: Inviter required")
	}
	if cfg.Cursor == nil {
		return nil, errors.New("apply: Cursor required")
	}
	if cfg.Reporter == nil {
		return nil, errors.New("apply: Reporter required")
	}
	if cfg.Metrics == nil {
		return nil, errors.New("apply: Metrics required")
	}
	if cfg.TenantID <= 0 {
		return nil, fmt.Errorf("apply: TenantID must be > 0 (got %d)", cfg.TenantID)
	}
	if cfg.BatchSize <= 0 {
		cfg.BatchSize = 100
	}
	if cfg.Retry == nil {
		cfg.Retry = &RetryPolicy{MaxAttempts: 5, Sleep: RealSleep}
	}
	return &Users{cfg: cfg}, nil
}

// Run executes phase 2. Loops until ListUsers returns an empty page;
// each iteration does at most BatchSize rows; cursor advances per row.
func (u *Users) Run(ctx context.Context) (Summary, error) {
	tenantStr := strconv.FormatInt(u.cfg.TenantID, 10)
	var sum Summary

	// Resolve the new-stack tenant UUID once at startup — every user
	// in this run targets the same tenant by definition (single-tenant
	// cutover, §3.2).
	tenantUUID, err := u.lookupTenant(ctx, u.cfg.TenantID)
	if err != nil {
		return sum, fmt.Errorf("apply: resolve tenant uuid for legacy %d: %w", u.cfg.TenantID, err)
	}

	// Read the resume point once. The persisted cursor is the "where
	// did the last apply leave off" anchor; from there we walk forward
	// in memory. Persisting per-row to KV is reserved for non-dry-run
	// (plan mode must not poison apply's resume state — see
	// TestRun_DryRunDoesNotAdvanceCursor).
	//
	// Tracking cursor locally also fixes issue #53: previously dry-run
	// re-fetched the same starting cursor every iteration, so the
	// reader returned the same page forever. With a local cursor that
	// always advances, plan mode terminates after one walk.
	cursor, _, err := u.cfg.Cursor.Get(ctx, binaryName, tenantStr, entityUsers)
	if err != nil {
		return sum, fmt.Errorf("apply: read cursor: %w", err)
	}

	for {
		rows, err := u.cfg.Reader.ListUsers(ctx, u.cfg.TenantID, cursor, u.cfg.BatchSize)
		if err != nil {
			return sum, fmt.Errorf("apply: list users: %w", err)
		}
		if len(rows) == 0 {
			break
		}

		for _, row := range rows {
			result, perRowErr := u.applyRow(ctx, row, tenantUUID, tenantStr)
			tally(&sum, result)
			if perRowErr != nil {
				return sum, perRowErr
			}
			cursor = row.ID
			if !u.cfg.DryRun {
				if putErr := u.cfg.Cursor.Put(ctx, binaryName, tenantStr, entityUsers, row.ID); putErr != nil {
					return sum, fmt.Errorf("apply: cursor put after row %d: %w", row.ID, putErr)
				}
			}
		}
	}

	u.cfg.Metrics.SetLagRows(ctx, tenantStr, entityUsers, 0)
	return sum, nil
}

// rowResult is the verdict for a single row, used by tally to
// increment the right Summary field.
type rowResult int

const (
	resultCreated rowResult = iota
	resultUpserted
	resultSkipped
	resultErrored
)

func tally(s *Summary, r rowResult) {
	switch r {
	case resultCreated, resultUpserted:
		s.Applied++
	case resultSkipped:
		s.Rejected++
	case resultErrored:
		s.Errored++
	}
	s.Planned++
}

// applyRow handles one legacy users row end-to-end: map, Invite with
// retry, dispatch error matrix. Returns (result, hardFailErr) — non-nil
// err aborts the whole loop; nil err means continue (even on rejection
// or per-row error).
func (u *Users) applyRow(ctx context.Context, row legacy.User, tenantUUID, tenantStr string) (rowResult, error) {
	u.cfg.Metrics.RowsPlanned(ctx, tenantStr, entityUsers)

	// Map row → InviteRequest.
	req, err := mapper.User(row, tenantUUID, u.cfg.DryRun)
	if err != nil {
		u.writeRejection(row, "MAPPER_VALIDATION", err.Error())
		u.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityUsers, "MAPPER_VALIDATION")
		u.cfg.Metrics.RowsApplied(ctx, tenantStr, entityUsers, "skipped")
		return resultSkipped, nil
	}

	startedAt := time.Now()
	var verdict rowResult
	inviteErr := WithBackoff(ctx, *u.cfg.Retry, func() (RetryDecision, error) {
		_, callErr := u.cfg.Inviter.Invite(ctx, req)
		if callErr == nil {
			verdict = resultCreated
			return RetryDecisionDone, nil
		}
		st, ok := status.FromError(callErr)
		if !ok {
			return RetryDecisionRetry, callErr
		}
		switch st.Code() {
		case codes.OK:
			verdict = resultCreated
			return RetryDecisionDone, nil
		case codes.AlreadyExists:
			verdict = resultUpserted
			return RetryDecisionDone, nil
		case codes.InvalidArgument:
			verdict = resultSkipped
			u.writeRejection(row, st.Code().String(), st.Message())
			u.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityUsers, st.Code().String())
			return RetryDecisionDone, nil
		case codes.PermissionDenied:
			return RetryDecisionHardFail,
				fmt.Errorf("apply: PERMISSION_DENIED on Invite (check migration:write scope): %w", callErr)
		case codes.Unavailable, codes.DeadlineExceeded:
			return RetryDecisionRetry, callErr
		default:
			return RetryDecisionHardFail, callErr
		}
	})
	u.cfg.Metrics.RecordApplyDuration(ctx, tenantStr, entityUsers, time.Since(startedAt))
	if inviteErr != nil {
		u.cfg.Metrics.RowsApplied(ctx, tenantStr, entityUsers, "errored")
		return resultErrored, inviteErr
	}

	switch verdict {
	case resultCreated:
		u.cfg.Metrics.RowsApplied(ctx, tenantStr, entityUsers, "created")
	case resultUpserted:
		u.cfg.Metrics.RowsApplied(ctx, tenantStr, entityUsers, "upserted")
	case resultSkipped:
		u.cfg.Metrics.RowsApplied(ctx, tenantStr, entityUsers, "skipped")
	}
	return verdict, nil
}

// lookupTenant resolves the legacy organization_id → new tenant UUID
// at startup. Phase 2 only ever migrates one tenant per run, so this
// is a single RPC per process.
func (u *Users) lookupTenant(ctx context.Context, legacyTenantID int64) (string, error) {
	resp, err := u.cfg.Tenants.GetByLegacyId(ctx, &tenantv1.GetByLegacyIdRequest{
		LegacyId: &commonv1.LegacyID{Value: strconv.FormatInt(legacyTenantID, 10)},
	})
	if err != nil {
		return "", err
	}
	id := resp.GetTenant().GetId()
	if id == "" {
		return "", fmt.Errorf("apply: tenant lookup returned empty UUID for legacy %d (phase 1 incomplete?)", legacyTenantID)
	}
	return id, nil
}

func (u *Users) writeRejection(row legacy.User, code, msg string) {
	_ = u.cfg.Reporter.Write(migrator.RejectionEntry{
		LegacyID:  strconv.FormatInt(row.ID, 10),
		Entity:    entityUsers,
		ErrorCode: code,
		ErrorMsg:  msg,
		Timestamp: time.Now(),
	})
}


