type fakeReader struct {
	pages [][]legacy.User
	calls int
	err   error
}

func (f *fakeReader) ListUsers(_ context.Context, _, _ int64, _ int) ([]legacy.User, error) {
	if f.err != nil {
		return nil, f.err
	}
	defer func() { f.calls++ }()
	if f.calls < len(f.pages) {
		return f.pages[f.calls], nil
	}
	return nil, nil
}

// cursorReader mimics the real legacy.Reader's cursor semantics:
// ListUsers returns rows whose ID is strictly greater than `cursor`,
// in ID order, capped at `limit`. Used by tests that need to verify
// the apply loop advances the cursor between iterations — without
// cursor-respecting behavior, the in-memory fake hides the bug from
// issue #53 (plan mode looped forever because the cursor never
// advanced and ListUsers kept returning the same rows).
type cursorReader struct {
	rows  []legacy.User
	calls int
}

func (c *cursorReader) ListUsers(_ context.Context, _, cursor int64, limit int) ([]legacy.User, error) {
	c.calls++
	out := make([]legacy.User, 0, limit)
	for _, r := range c.rows {
		if r.ID <= cursor {
			continue
		}
		out = append(out, r)
		if len(out) >= limit {
			break
		}
	}
	return out, nil
}

type fakeTenants struct {
	resp *tenantv1.GetByLegacyIdResponse
	err  error
}

func (f *fakeTenants) GetByLegacyId(_ context.Context, _ *tenantv1.GetByLegacyIdRequest) (*tenantv1.GetByLegacyIdResponse, error) {
	return f.resp, f.err
}

type fakeInviter struct {
	// errs is consumed in order across calls; once exhausted, the last
	// value sticks (so a test can pin "every subsequent call returns X").
	errs    []error
	calls   int
	lastReq *userv1.InviteRequest
}

func (f *fakeInviter) Invite(_ context.Context, req *userv1.InviteRequest) (*userv1.InviteResponse, error) {
	f.lastReq = req
	idx := f.calls
	if idx >= len(f.errs) {
		idx = len(f.errs) - 1
	}
	f.calls++
	if idx < 0 || f.errs[idx] == nil {
		return &userv1.InviteResponse{
			User: &userv1.User{Id: "user-uuid"},
		}, nil
	}
	return nil, f.errs[idx]
}

type fakeCursor struct {
	store map[string]int64
}

func (f *fakeCursor) Get(_ context.Context, _, _, _ string) (int64, bool, error) {
	if f.store == nil {
		return 0, false, nil
	}
	v, ok := f.store["k"]
	return v, ok, nil
}

func (f *fakeCursor) Put(_ context.Context, _, _, _ string, off int64) error {
	if f.store == nil {
		f.store = map[string]int64{}
	}
	f.store["k"] = off
	return nil
}

type fakeReporter struct {
	entries []migrator.RejectionEntry
